head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[multiselect > P > singleSelect]<br/>MultiSelect 컴포넌트에서 하나의 아이템만 선택 가능하도록 제한할지 설정합니다.",
    "validation" : [
        "true 설정 시 한 개의 아이템만 선택할 수 있습니다.",
        "true 설정 시 새로운 아이템을 선택하면 기존 선택 아이템이 자동으로 해제됩니다.",
        "false (default) 설정 시 한 개 이상의 아이템을 선택할 수 있습니다.",
        "singleSelect=true 일때 setSelectedIndex() 메소드에서 여러개의 인덱스를 설정하면 첫 번째 인덱스만 선택됩니다.",
        // "accessibility=true 이고 singleSelect=true 이면 Enter 키로도 아이템을 선택할 수 있습니다. (multiselect_P_accessibility_1 에서 검증)",
    ]
}



scwin.onpageload = function () {
    $c.gcm.createCommonDatalist();
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
    scwin.comp_init();
};



// comp 생성 (createBasicMultiSelect 로 동적 생성, singleSelect 속성 적용)
scwin.comp_init = async function () {
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    $c.gcm.createDataListMultiSelect();

    let cSingleSelect = con_singleSelect.getText();

    let properties = {};
    if (cSingleSelect !== "") {
        properties.singleSelect = cSingleSelect;
    }
    let cList = $c.gcm.createCList(properties);

    $c.gcm.createLabel('label="target1 : singleSelect=[' + (cSingleSelect === "" ? "미설정(기본 false)" : cSingleSelect) + ']"', '', 'label1');
    $c.gcm.createBasicMultiSelect(cList);
};



// setSelectedIndex - 다중 인덱스 설정 (singleSelect=true 면 첫 번째만, false 면 모두 토글)
scwin.btn_setSelectedIndex_onclick = function (e) {
    target1.setValue("");
    target1.setSelectedIndex("0 1 2");
    wf_body_bottom.getObj("scwin").setReturnValue("target1.setSelectedIndex('0 1 2') 호출 완료");
};



// 현재 선택값 확인 (getValue + getSelectedIndex)
scwin.btn_getValue_onclick = function (e) {
    wf_body_bottom.getObj("scwin").setReturnValue("getValue() : [" + target1.getValue() + "]");
    wf_body_bottom.getObj("scwin").setReturnValue("getSelectedIndex() : [" + target1.getSelectedIndex() + "]");
};
